create or replace function public.collect_sellertray_customer_receivable(p_tenant_id uuid,p_order_id uuid,p_payment_method_id uuid,p_amount numeric,p_command_id uuid)
returns jsonb language plpgsql security definer set search_path=''
as $$declare v_user_id uuid:=auth.uid();v_order public.orders%rowtype;v_method text;v_status text;v_result jsonb;v_amount numeric:=round(coalesce(p_amount,0),2);begin if v_user_id is null then raise exception 'SellerTray authentication required' using errcode='42501';end if;if p_command_id is null then raise exception 'Payment command identity is required' using errcode='22023';end if;if v_amount<=0 then raise exception 'Payment amount must be greater than zero' using errcode='22023';end if;if not public.orderdesk_subscription_can_write(p_tenant_id) then raise exception 'SellerTray subscription is read-only' using errcode='42501';end if;select * into v_order from public.orders o where o.tenant_id=p_tenant_id and o.id=p_order_id and o.deleted_at is null for update;if not found then raise exception 'Sale not found' using errcode='P0002';end if;if v_order.status<>'completed' or v_order.customer_id is null then raise exception 'Only a completed named-customer sale can receive a balance payment' using errcode='23514';end if;if not public.sellertray_user_can_operate_branch(p_tenant_id,v_order.branch_id,v_user_id) or not public.sellertray_user_has_capability(p_tenant_id,v_user_id,'can_manage_order_payment') then raise exception 'You do not have permission to collect this customer balance' using errcode='42501';end if;if v_amount>greatest(v_order.total_amount-v_order.amount_paid,0)+0.005 then raise exception 'Payment exceeds the outstanding customer balance' using errcode='23514';end if;if p_payment_method_id is null then v_method:='cash';v_status:='confirmed';else select m.method_type into v_method from public.sellertray_branch_payment_methods bpm join public.merchant_payment_methods m on m.tenant_id=bpm.tenant_id and m.id=bpm.payment_method_id where bpm.tenant_id=p_tenant_id and bpm.branch_id=v_order.branch_id and bpm.payment_method_id=p_payment_method_id and bpm.is_enabled=true and m.is_enabled=true and m.method_type in('bank_transfer','card_terminal');if not found then raise exception 'Payment method is not enabled for this Branch' using errcode='23514';end if;v_status:=case when v_method='bank_transfer' then 'pending_verification' else 'confirmed' end;end if;v_result:=public.sellertray_record_pos_payment_allocation(p_tenant_id,p_order_id,p_payment_method_id,v_amount,v_status,v_user_id,'receivable:'||p_command_id::text);return coalesce(v_result,'{}'::jsonb)||jsonb_build_object('orderId',p_order_id,'amount',v_amount,'methodType',v_method,'status',v_status);end$$;
revoke all on function public.collect_sellertray_customer_receivable(uuid,uuid,uuid,numeric,uuid) from public,anon;grant execute on function public.collect_sellertray_customer_receivable(uuid,uuid,uuid,numeric,uuid) to authenticated,service_role;
